// Turn an incoming order/payment payload into pdfmill invoice data, with computed totals.
// Works with any source — a Stripe/Shopify webhook, a form, or a raw POST. Map your fields here.
const body = $json.body ?? $json;
const rawItems = Array.isArray(body.items) ? body.items : (Array.isArray(body.line_items) ? body.line_items : []);
const isValid = rawItems.length > 0;

const items = rawItems.map((i) => {
  const quantity = Number(i.quantity ?? 1);
  const unitPrice = Number(i.unitPrice ?? i.price ?? i.amount ?? 0);
  return {
    description: i.description ?? i.name ?? i.title ?? 'Item',
    quantity,
    unitPrice,
    lineTotal: Math.round(quantity * unitPrice * 100) / 100,
  };
});

const subtotal = Math.round(items.reduce((sum, i) => sum + i.lineTotal, 0) * 100) / 100;
const taxRate = Number(body.taxRate ?? 0); // percentage, e.g. 8.5
const taxAmount = Math.round(subtotal * taxRate) / 100;
const total = Math.round((subtotal + taxAmount) * 100) / 100;

const today = new Date();
const iso = (d) => d.toISOString().slice(0, 10);
const due = new Date(today.getTime() + 30 * 24 * 60 * 60 * 1000);

return [{
  json: {
    isValid,
    invoiceNumber: body.invoiceNumber ?? ('INV-' + iso(today).replace(/-/g, '') + '-' + String(body.orderId ?? body.id ?? Math.floor(today.getTime() / 1000)).slice(-4)),
    issuedAt: iso(today),
    dueAt: iso(due),
    paymentTerms: 'Net 30',
    currency: body.currency ?? 'USD',
    from: body.from ?? { name: 'Your Company LLC', address: '123 Main Street, Your City, ST 00000', email: 'user@example.com' },
    billTo: {
      name: body.customer?.name ?? body.customerName ?? body.name ?? 'Customer',
      address: body.customer?.address ?? body.billingAddress ?? '',
      email: body.customer?.email ?? body.email ?? '',
    },
    items,
    subtotal,
    taxRate,
    taxAmount,
    total,
    notes: body.notes ?? 'Payment due within 30 days. Thank you for your business.',
  },
}];

